-- ========================= STORED PROCEDURES =========================


-- ---------- Profiler.usp_InsertProfilerRecommendation ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_InsertProfilerRecommendation] 
	@MandateId UNIQUEIDENTIFIER
	,@ForPaymentCycle INT
	,@CollectionMethod VARCHAR(50)
	,@ServiceType VARCHAR(50)
	,@TrackingDays INT
	,@MandateDRI INT
	,@RecommendationTypes VARCHAR(MAX)
	,@ProfileDateId INT
	,@SourcePaymentId INT
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @ProfilerRecommendationId INT

	SELECT TOP 1 @ProfilerRecommendationId = ProfilerRecommendationId
	FROM [Profiler].[ProfilerRecommendation] WITH (NOLOCK)
	WHERE [MandateId] = @MandateId
		AND [ForPaymentCycle] = @ForPaymentCycle

	IF @ProfilerRecommendationId IS NOT NULL
	BEGIN
		SELECT @ProfilerRecommendationId AS ProfilerRecommendationId
			,1 AS [AlreadyExists]
	END
	ELSE
	BEGIN
		INSERT INTO [Profiler].[ProfilerRecommendation] (
			[MandateId]
			,[ForPaymentCycle]
			,[CollectionMethod]
			,[ServiceType]
			,[TrackingDays]
			,[MandateDRI]
			,[RecommendationTypes]
			,[ProfileDateId]
			,[SourcePaymentId]
			,[InsertedOn]
			)
		OUTPUT INSERTED.ProfilerRecommendationId
			,0 AS [AlreadyExists]
		VALUES (
			@MandateId
			,@ForPaymentCycle
			,@CollectionMethod
			,@ServiceType
			,@TrackingDays
			,@MandateDRI
			,@RecommendationTypes
			,@ProfileDateId
			,@SourcePaymentId
			,GETDATE()
			)
	END
END

RETURN 0
GO


-- ---------- Profiler.usp_UpdateProfilerRecommendation ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_UpdateProfilerRecommendation] @ProfilerRecommendationId INT
	,@CollectionMethod VARCHAR(50)
	,@ServiceType VARCHAR(50)
	,@TrackingDays INT
	,@MandateDRI INT
	,@RecommendationTypes VARCHAR(MAX)
	,@ProfileDateId INT
	,@SourcePaymentId INT
AS
BEGIN
	SET NOCOUNT ON

	UPDATE [Profiler].[ProfilerRecommendation]
	SET [CollectionMethod] = @CollectionMethod
		,[ServiceType] = @ServiceType
		,[TrackingDays] = @TrackingDays
		,[MandateDRI] = @MandateDRI
		,[RecommendationTypes] = @RecommendationTypes
		,[ProfileDateId] = @ProfileDateId
		,[SourcePaymentId] = @SourcePaymentId
	OUTPUT INSERTED.ProfilerRecommendationId
	WHERE [ProfilerRecommendationId] = @ProfilerRecommendationId

	RETURN 0
END
GO


-- ---------- Profiler.usp_GetProfilerRecommendation ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_GetProfilerRecommendation] @MandateId UNIQUEIDENTIFIER
	,@ForPaymentCycle INT
AS
BEGIN
	SET NOCOUNT ON

	SELECT TOP 1 [PR].[ProfilerRecommendationId]
		,[PR].[MandateId]
		,[PR].[ForPaymentCycle]
		,[PD].[CollectionDate]
		,[PR].[CollectionMethod]
		,[PR].[ServiceType]
		,[PR].[TrackingDays]
		,[PR].[MandateDRI]
		,[PR].[RecommendationTypes]
		,[PR].[ProfileDateId]
		,[PD].[ProfileId]
		,[PR].SourcePaymentId
		,[PR].[InsertedOn]
	FROM [Profiler].[ProfilerRecommendation] PR WITH (NOLOCK)
	INNER JOIN [Profiler].[ProfileDates] PD WITH (NOLOCK) ON [PD].[ProfileDateId] = [PR].[ProfileDateId]
	WHERE [PR].[MandateId] = @MandateId
		AND [PR].[ForPaymentCycle] = @ForPaymentCycle
	ORDER BY [PR].[ProfilerRecommendationId] DESC
END

RETURN 0
GO


-- ---------- Profiler.usp_ResetMandateScores ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_ResetMandateScores]
	@ScoreAdjustmentReason varchar(200)
	,@MandateId uniqueIdentifier
AS

Update [Profiler].[MandateScores]
set 
	 [Score] = 0
	,[ScoreAdjustmentReason] = @ScoreAdjustmentReason
	,[ScoreAdjustedOn] = getdate()
where [MandateId] = @MandateId
and coalesce([Score],0) <> 0

RETURN 0
GO


-- ---------- Profiler.usp_AddNewDebitRunIdProfileAsTied ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_AddNewDebitRunIdProfileAsTied] @MandateId UNIQUEIDENTIFIER
	,@NewDebitRunId INT
	,@PaymentCycle INT
	,@ScoreAdjustmentReason VARCHAR(200)
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @ProcessResult AS VARCHAR(50)
	DECLARE @TransactionDate AS DATETIME = GETDATE()
	DECLARE @NewProfileId VARCHAR(50)
	DECLARE @NewDRITotalScore INT = 0
	DECLARE @HighestOtherDRIScore INT = 0

	SELECT TOP 1 @NewProfileId = ProfileId
	FROM [Profiler].[ProfileDates] WITH (NOLOCK)
	WHERE [DebitRunId] = @NewDebitRunId
		AND [PaymentCycle] = @PaymentCycle
	ORDER BY [CollectionDate] ASC

	SELECT @NewDRITotalScore = sum(score)
	FROM [Profiler].[MandateScores]
	WHERE [MandateId] = @MandateId
		AND [Score] > 0
		AND [DebitRunId] = @NewDebitRunId
	GROUP BY [DebitRunId]

	IF NOT EXISTS (
			/*Check to ensure the DRI and Profile has not failed previously*/
			SELECT 1
			FROM [Profiler].[MandateScores] WITH (NOLOCK)
			WHERE [MandateId] = @MandateId
				AND [DebitRunId] = @NewDebitRunId
				AND (
					[ProfileId] = @NewProfileId
					OR [ProfileId] = 'Weekday'
					)
				AND [Score] = - 1
			)
	BEGIN /*To add new DRI check if there are any other positive scores*/
		SET @HighestOtherDRIScore = (
				SELECT TOP 1 sum([Score]) AS TotalPositiveScore
				FROM [Profiler].[MandateScores]
				INNER JOIN [Profiler].[DebitRunIds] ON [DebitRunIds].[DebitRunId] = [MandateScores].[DebitRunId]
					AND [DebitRunIds].[IsDeleted] = 0
				WHERE [MandateId] = @MandateId
					AND [Score] > 0
					AND [MandateScores].[DebitRunId] <> @NewDebitRunId
				GROUP BY [MandateScores].[DebitRunId]
				ORDER BY 1 DESC
				)

		IF coalesce(@HighestOtherDRIScore, 0) > @NewDRITotalScore
		BEGIN
			MERGE [Profiler].[MandateScores] WITH (
					ROWLOCK
					,UPDLOCK
					) AS MandateScores
			USING (
				VALUES (
					@NewDebitRunId
					,@NewProfileId
					,@MandateId
					)
				) AS [NewDRIProfile](DebitRunId, ProfileId, MandateId)
				ON [MandateScores].[ProfileId] = [NewDRIProfile].[ProfileId]
					AND [MandateScores].[DebitRunId] = [NewDRIProfile].[DebitRunId]
					AND [MandateScores].[MandateId] = [NewDRIProfile].[MandateId]
			WHEN MATCHED
				THEN
					UPDATE
					SET [MandateScores].[Score] = [MandateScores].[Score] + (@HighestOtherDRIScore - @NewDRITotalScore)
						,[MandateScores].[PaymentCycle] = @PaymentCycle
						,[MandateScores].[ScoreAdjustedOn] = getdate()
						,[MandateScores].[ScoreAdjustmentReason] = @ScoreAdjustmentReason
			WHEN NOT MATCHED BY TARGET
				THEN
					INSERT (
						[MandateId]
						,[ProfileId]
						,DebitRunId
						,[PaymentCycle]
						,[ScoredOn]
						,[Score]
						,[ScoreAdjustedOn]
						,[ScoreAdjustmentReason]
						)
					VALUES (
						@MandateId
						,[NewDRIProfile].[ProfileId]
						,[NewDRIProfile].[DebitRunId]
						,@PaymentCycle
						,getdate()
						,@HighestOtherDRIScore - @NewDRITotalScore
						,getdate()
						,@ScoreAdjustmentReason
						);
		END

		SET @ProcessResult = 'Tied DRI'
	END
	ELSE /*DRI not valid, dont add DRI*/
	BEGIN
		SET @ProcessResult = 'Skipped'
	END

	SELECT @ProcessResult AS ProcessResult
END

RETURN 0
GO


-- ---------- Profiler.usp_GetFirstEarlierCollectionDate ----------
CREATE OR ALTER PROCEDURE Profiler.usp_GetFirstEarlierCollectionDate (
	@Date DATE
	,@ForPaymentCycle INT
	,@IsWeekDay BIT
	,@TrackingDays INT = 10
	)
AS
BEGIN
	SET NOCOUNT ON
 
	DECLARE @CollectionDate DATE,
	@DebitRunId INT,
	@GrantCollectionDate DATE,
	@TrackingEndDate DATE;

	DECLARE @NextPaymentCycle INT = CONVERT(INT, FORMAT(DATEADD(MONTH, 1, CONVERT(DATE, CAST(@ForPaymentCycle AS CHAR(6)) + '01', 102)), 'yyyyMM'));
	DECLARE @NextMaxGrantDate DATE

	SELECT TOP 1 @NextMaxGrantDate = [CollectionDate]
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	INNER JOIN [Profiler].[GrantDates] gd WITH (NOLOCK) ON gd.[Date] = pd.[CollectionDate] and gd.PaymentCycle = pd.PaymentCycle
	WHERE pd.[PaymentCycle] = @NextPaymentCycle
	ORDER BY gd.[Date] DESC

	DECLARE @MaxTrackingDate DATE
	SELECT TOP 1 @MaxTrackingDate = ISNULL(@NextMaxGrantDate, pd.[CollectionDate])
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	WHERE pd.[PaymentCycle] = @NextPaymentCycle
		AND pd.[CollectionDate] <= DATEADD(MONTH, 1, CONVERT(DATE, CAST(@ForPaymentCycle AS CHAR(6)) + '07', 102))
	ORDER BY pd.[CollectionDate] DESC
 
	SELECT TOP 1 @CollectionDate = CollectionDate,@DebitRunId = DebitRunId
	FROM [Profiler].[ProfileDates] WITH (NOLOCK)
	WHERE CollectionDate < @Date
		AND PaymentCycle <= @ForPaymentCycle
		AND (
        @IsWeekDay = 0
        OR ProfileId = 'Weekday'
        )
	ORDER BY CollectionDate DESC
 
	SET @TrackingEndDate = DATEADD(DAY, @TrackingDays - 1, @CollectionDate);

	SELECT TOP 1 @CollectionDate AS CollectionDate
		,pd.[ProfileDateId]
		,CASE WHEN pd.[CollectionDate] >= @MaxTrackingDate THEN @MaxTrackingDate ELSE pd.[CollectionDate] END AS EndofTrackingDate
		,DATEDIFF(DAY,@CollectionDate,CASE WHEN pd.[CollectionDate] >= @MaxTrackingDate THEN @MaxTrackingDate ELSE pd.[CollectionDate] END) + 1 AS TrackingDays
		,@DebitRunId as CollectionDateDRI
		,pd.[PaymentCycle]
		,pd.[ProfileId]
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	INNER JOIN Profiler.Profiles p WITH (NOLOCK) on p.ProfileId = pd.ProfileId and p.IsDeleted = 0
	INNER JOIN Profiler.DebitRunIds d WITH (NOLOCK) on d.DebitRunId = pd.DebitRunId and d.IsDeleted = 0
	LEFT JOIN Profiler.GrantDates PG WITH (NOLOCK) on PG.PaymentCycle = pd.PaymentCycle
	WHERE CollectionDate <= @TrackingEndDate
	ORDER BY pd.CollectionDate DESC
END
GO


-- ---------- Profiler.usp_ClearLabelsForRecommendation ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_ClearLabelsForRecommendation] (@ProfilerRecommendationId INT)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @ProfilerRecommendationId IS NOT NULL
	BEGIN
		DELETE
		FROM Profiler.ProfilerRecommendationLabels
		WHERE ProfilerRecommendationld = @ProfilerRecommendationId
	END

	
END
GO


-- ---------- Profiler.usp_DeleteFutureProfilerRecommendation ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_DeleteFutureProfilerRecommendation] (
	@MandateId UNIQUEIDENTIFIER
	,@NextPaymentCycle INT
	)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @RecommendationCount INT;

	SELECT @RecommendationCount = COUNT(*)
	FROM [Profiler].[ProfilerRecommendation] with (nolock)
	WHERE MandateId = @MandateId
		AND ForPaymentCycle >= @NextPaymentCycle;

	IF @RecommendationCount = 1
	BEGIN
		BEGIN TRANSACTION;

		BEGIN TRY
			DELETE rl
			FROM [Profiler].[ProfilerRecommendationLabels] rl
			INNER JOIN [Profiler].[ProfilerRecommendation] pr with (nolock) ON rl.ProfilerRecommendationld = pr.ProfilerRecommendationId
			WHERE pr.MandateId = @MandateId
				AND pr.ForPaymentCycle = @NextPaymentCycle;

			DELETE
			FROM [Profiler].[ProfilerRecommendation]
			WHERE MandateId = @MandateId
				AND ForPaymentCycle = @NextPaymentCycle;

			COMMIT TRANSACTION;
		END TRY

		BEGIN CATCH
			ROLLBACK TRANSACTION;

			THROW;
		END CATCH
	END
END
GO


-- ---------- Profiler.usp_ApplyRelatedMandatesScoring ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_ApplyRelatedMandatesScoring] @TargetMandateId UNIQUEIDENTIFIER
	,@RelatedMandates VARCHAR(MAX)
	,@PaymentCycle INT
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @SystemDate DATETIME = GETDATE();

	WITH [PostiveScoreCheck] ([MandateId])
	AS (
		SELECT DISTINCT [MandateFilter].[MandateId]
		FROM [Profiler].[MandateScores] AS [MandateFilter] WITH (NOLOCK)
		WHERE [MandateFilter].[MandateId] IN (
				SELECT value
				FROM STRING_SPLIT(@RelatedMandates, ',')
				)
			AND [MandateFilter].[Score] > 0
			AND CAST([MandateFilter].[PaymentCycle] AS INT) >= @PaymentCycle
			AND [MandateFilter].[ScoreAdjustmentReason] NOT LIKE '%ALGN%'
		)
		,[MandateScoresToCopy] (
		[TargetMandateId]
		,[MandateId]
		,[ProfileId]
		,[DebitRunId]
		,[PaymentCycle]
		,[ScoredOn]
		,[Score]
		,[ScoreAdjustedOn]
		,[ScoreAdjustmentReason]
		)
	AS (
		SELECT [TargetMandateId]
			,[MandateId]
			,[ProfileId]
			,[DebitRunId]
			,[PaymentCycle]
			,[ScoredOn]
			,[Score]
			,[ScoreAdjustedOn]
			,[ScoreAdjustmentReason]
		FROM (
			SELECT @TargetMandateId AS TargetMandateId
				,[ScoresToCopy].[MandateId]
				,[ScoresToCopy].[ProfileId]
				,[ScoresToCopy].[DebitRunId]
				,[ScoresToCopy].[PaymentCycle]
				,[ScoresToCopy].[ScoredOn]
				,[ScoresToCopy].[Score]
				,[ScoresToCopy].[ScoreAdjustedOn]
				,[ScoresToCopy].[ScoreAdjustmentReason]
				,ROW_NUMBER() OVER (
					PARTITION BY [ScoresToCopy].[ProfileId]
					,[ScoresToCopy].[DebitRunId] ORDER BY [ScoresToCopy].[Score] DESC
						,COALESCE([ScoresToCopy].[ScoreAdjustedOn], COALESCE([ScoresToCopy].[ScoredOn], 0)) DESC
					) AS ranking
				,COALESCE([ScoresToCopy].[ScoreAdjustedOn], [ScoresToCopy].[ScoredOn]) CopyScoredOn
				,COALESCE([TargetMandateScores].[ScoreAdjustedOn], COALESCE([TargetMandateScores].[ScoredOn], 0)) TargetScoredOn
			FROM [Profiler].[MandateScores] AS [ScoresToCopy] WITH (NOLOCK)
			INNER JOIN [PostiveScoreCheck] ON [PostiveScoreCheck].[MandateId] = [ScoresToCopy].[MandateId]
				AND [PostiveScoreCheck].[MandateId] <> @TargetMandateId
			LEFT OUTER JOIN [Profiler].[MandateScores] AS [TargetMandateScores] WITH (NOLOCK) ON [TargetMandateScores].[ProfileId] = [ScoresToCopy].[ProfileId]
				AND [TargetMandateScores].[DebitRunId] = [ScoresToCopy].[DebitRunId]
				AND [TargetMandateScores].[MandateId] = @TargetMandateId
			WHERE [ScoresToCopy].[ScoreAdjustmentReason] NOT LIKE '%' + CONVERT(NVARCHAR(36), @TargetMandateId) + '%'
			) AS RankedData
		WHERE ranking = 1
		)
	MERGE [Profiler].[MandateScores] WITH (
			ROWLOCK
			,UPDLOCK
			) AS [MandateScores]
	USING MandateScoresToCopy
		ON MandateScoresToCopy.[ProfileId] = [MandateScores].[ProfileId]
			AND MandateScoresToCopy.[DebitRunId] = [MandateScores].[DebitRunId]
			AND MandateScoresToCopy.TargetMandateId = [MandateScores].[MandateId]
	WHEN MATCHED
		THEN
			UPDATE
			SET [MandateScores].[Score] = MandateScoresToCopy.[Score]
				,[MandateScores].[PaymentCycle] = @PaymentCycle
				,[MandateScores].[ScoreAdjustedOn] = @SystemDate
				,[MandateScores].[ScoreAdjustmentReason] = 'ALGN Scoring Updated from ' + CAST(MandateScoresToCopy.[MandateId] AS VARCHAR(MAX)) + ' For ' + CAST(@PaymentCycle AS VARCHAR)
	WHEN NOT MATCHED BY TARGET
		THEN
			INSERT (
				[MandateId]
				,[ProfileId]
				,[DebitRunId]
				,[PaymentCycle]
				,[ScoredOn]
				,[Score]
				,[ScoreAdjustedOn]
				,[ScoreAdjustmentReason]
				)
			VALUES (
				@TargetMandateId
				,MandateScoresToCopy.[ProfileId]
				,MandateScoresToCopy.DebitRunId
				,@PaymentCycle
				,@SystemDate
				,MandateScoresToCopy.[Score]
				,@SystemDate
				,'ALGN Scoring Copied from ' + cast(MandateScoresToCopy.[MandateId] AS VARCHAR(MAX)) + ' For ' + CAST(@PaymentCycle AS VARCHAR)
				)
	OUTPUT $ACTION AS [Action]
		,[INSERTED].[MandateId]
		,[INSERTED].[ProfileId]
		,[INSERTED].[DebitRunId]
		,[INSERTED].[PaymentCycle]
		,[INSERTED].[ScoredOn]
		,[INSERTED].[Score]
		,[INSERTED].[ScoreAdjustedOn]
		,[INSERTED].[ScoreAdjustmentReason];
END

RETURN 0
GO


-- ---------- Profiler.usp_ScoreMandateCollectionDates ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_ScoreMandateCollectionDates] @MandateId UNIQUEIDENTIFIER
	,@ResultPaymentCycle INT
	,@ResultPresentedOnDate DATE
	,@ResultDate DATE
	,@ResultType VARCHAR(20)
	,@ResultMethod VARCHAR(50)
	,@MandateCanTrack BIT
AS
BEGIN
	SET NOCOUNT ON

	DECLARE @NextPaymentCycle INT = CONVERT(INT, FORMAT(DATEADD(MONTH, 1, CONVERT(DATE, CAST(@ResultPaymentCycle AS CHAR(6)) + '01', 102)), 'yyyyMM'));
	DECLARE @NextPaymentDate DATE

	SET @NextPaymentDate = (
			SELECT ISNULL(MAX([Date]), CONCAT (
						LEFT(@NextPaymentCycle, 4)
						,'-'
						,RIGHT(@NextPaymentCycle, 2)
						,'-07'
						))
			FROM Profiler.GrantDates WITH (NOLOCK)
			WHERE PaymentCycle = @NextPaymentCycle
			)

	-- Score Collection Results
	MERGE [Profiler].[MandateScores] WITH (
			ROWLOCK
			,UPDLOCK
			) AS MandateScores
	USING (
		SELECT ProfileDateId
			,CollectionDate
			,pd.DebitRunId
			,pd.ProfileId
		FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
		LEFT OUTER JOIN [Profiler].[MandateScores] ms WITH (NOLOCK) ON ms.MandateId = @MandateId
			AND ms.PaymentCycle >= @ResultPaymentCycle
			AND pd.DebitRunId = ms.DebitRunId
			AND pd.ProfileId = ms.ProfileId
		WHERE pd.CollectionDate BETWEEN cast(@ResultPresentedOnDate AS DATE)
				AND cast(@ResultDate AS DATE)
			AND ms.MandateId IS NULL
		) AS [ProfileDates]
		ON [MandateScores].ProfileId = [ProfileDates].ProfileId
			AND [MandateScores].DebitRunId = [ProfileDates].DebitRunId
			AND [MandateScores].MandateId = @MandateId
	WHEN MATCHED
		THEN
			UPDATE
			SET [MandateScores].[Score] = CASE 
					WHEN @ResultType = 'Success'
						AND @ResultDate = [ProfileDates].CollectionDate
						THEN CASE 
								WHEN [MandateScores].[Score] = - 1
									THEN 1
								ELSE [MandateScores].[Score] + 1
								END
					ELSE - 1
					END
				,[MandateScores].[PaymentCycle] = @ResultPaymentCycle
				,[MandateScores].[ScoreAdjustedOn] = getdate()
				,[MandateScores].[ScoreAdjustmentReason] = 'Scoring for ' + cast(@ResultPaymentCycle AS VARCHAR)
	WHEN NOT MATCHED BY TARGET
		THEN
			INSERT (
				[MandateId]
				,[ProfileId]
				,DebitRunId
				,[PaymentCycle]
				,[ScoredOn]
				,[Score]
				,[ScoreAdjustedOn]
				,[ScoreAdjustmentReason]
				)
			VALUES (
				@MandateId
				,[ProfileDates].[ProfileId]
				,[ProfileDates].DebitRunId
				,@ResultPaymentCycle
				,getdate()
				,CASE 
					WHEN @ResultType = 'Success'
						AND @ResultDate = [ProfileDates].[CollectionDate]
						THEN 1
					ELSE - 1
					END
				,getdate()
				,'NewProfiles for ' + cast(@ResultPaymentCycle AS VARCHAR)
				);

	-- Fully Covered Set to - 1 in result Payment Cycle
	MERGE [Profiler].[MandateScores] WITH (
			ROWLOCK
			,UPDLOCK
			) AS MandateScores
	USING (
		SELECT [DebitRunId]
			,[ScoredCount]
			,[ProfileDateCount]
			,'FullyCovered' AS [ProfileId]
		FROM (
			SELECT cpd.[DebitRunId]
				,sum(CASE 
						WHEN coalesce(cms.[Score], 0) = - 1
							THEN 1
						ELSE 0
						END) AS ScoredCount
				,count(*) AS ProfileDateCount
			FROM Profiler.ProfileDates cpd WITH (NOLOCK)
			LEFT OUTER JOIN Profiler.MandateScores cms WITH (NOLOCK) ON cms.DebitRunId = cpd.DebitRunId
				AND cms.ProfileId = cpd.ProfileId
				AND cms.MandateId = @MandateId
			WHERE cpd.PaymentCycle BETWEEN @ResultPaymentCycle
					AND @NextPaymentCycle
				AND cpd.CollectionDate <= @NextPaymentDate
				AND cpd.CollectionDate >= @ResultPresentedOnDate
				AND cpd.ProfileId NOT LIKE 'LastDay-ClearsIn%'
			GROUP BY cpd.[DebitRunId]
			) AS MandateProfileDRICoverage
		WHERE ScoredCount = ProfileDateCount
		) AS FullyCoveredSource
		ON MandateScores.DebitRunId = FullyCoveredSource.DebitRunId
			AND MandateScores.ProfileId = FullyCoveredSource.ProfileId
			AND [MandateScores].MandateId = @MandateId
	WHEN MATCHED
		THEN
			UPDATE
			SET [MandateScores].[Score] = - 1
				,[MandateScores].[PaymentCycle] = @ResultPaymentCycle
				,[MandateScores].[ScoreAdjustedOn] = getdate()
				,[MandateScores].[ScoreAdjustmentReason] = 'Scoring for ' + cast(@ResultPaymentCycle AS VARCHAR)
	WHEN NOT MATCHED BY TARGET
		THEN
			INSERT (
				[MandateId]
				,[ProfileId]
				,DebitRunId
				,[PaymentCycle]
				,[ScoredOn]
				,[Score]
				,[ScoreAdjustedOn]
				,[ScoreAdjustmentReason]
				)
			VALUES (
				@MandateId
				,[FullyCoveredSource].[ProfileId]
				,[FullyCoveredSource].DebitRunId
				,@ResultPaymentCycle
				,getdate()
				,- 1
				,getdate()
				,'NewProfiles for ' + cast(@ResultPaymentCycle AS VARCHAR)
				);

	-- Set historic fullycoverd as 0 for success on matching DRI
	UPDATE HistoricFullyCovered
	SET HistoricFullyCovered.Score = 0
	FROM Profiler.MandateScores HistoricFullyCovered WITH (
			ROWLOCK
			,UPDLOCK
			)
	INNER JOIN Profiler.MandateScores OtherMandatesDRIs WITH (NOLOCK) ON OtherMandatesDRIs.MandateId = HistoricFullyCovered.MandateId
		AND OtherMandatesDRIs.ProfileId <> 'FullyCovered'
		AND OtherMandatesDRIs.DebitRunId = HistoricFullyCovered.DebitRunId
		AND OtherMandatesDRIs.Score > 0
		AND OtherMandatesDRIs.ProfileId NOT LIKE 'LastDay-ClearsIn%'
	WHERE HistoricFullyCovered.MandateId = @MandateId
		AND HistoricFullyCovered.ProfileId = 'FullyCovered'
		AND HistoricFullyCovered.Score = - 1
		AND HistoricFullyCovered.PaymentCycle < OtherMandatesDRIs.PaymentCycle

	-- All new fully covered and weekday set other Matching DRI as - 1
	UPDATE OtherMandatesDRIs
	SET OtherMandatesDRIs.Score = - 1
		,OtherMandatesDRIs.PaymentCycle = FailedWeekdays.PaymentCycle
		,OtherMandatesDRIs.ScoreAdjustedOn = FailedWeekdays.ScoreAdjustedOn
		,OtherMandatesDRIs.ScoreAdjustmentReason = FailedWeekdays.ScoreAdjustmentReason
	FROM Profiler.MandateScores OtherMandatesDRIs WITH (
			ROWLOCK
			,UPDLOCK
			)
	INNER JOIN Profiler.MandateScores FailedWeekdays WITH (NOLOCK) ON FailedWeekdays.MandateId = OtherMandatesDRIs.MandateId
		AND FailedWeekdays.ProfileId IN (
			'Weekday'
			,'FullyCovered'
			)
		AND FailedWeekdays.DebitRunId = OtherMandatesDRIs.DebitRunId
		AND FailedWeekdays.ProfileId <> OtherMandatesDRIs.ProfileId
		AND FailedWeekdays.Score = - 1
	WHERE OtherMandatesDRIs.MandateId = @MandateId
		AND OtherMandatesDRIs.PaymentCycle < FailedWeekdays.PaymentCycle
		AND OtherMandatesDRIs.ProfileId NOT LIKE 'LastDay-ClearsIn%'
		AND OtherMandatesDRIs.Score > 0
END
GO


-- ---------- Profiler.usp_GetMandateScoredResults ----------
CREATE OR ALTER PROCEDURE [Profiler].[usp_GetMandateScoredResults] @MandateId UNIQUEIDENTIFIER
	,@ForPaymentCycle INT
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @FilterScoreDatesTable TABLE (DebitRunId INT);

	INSERT INTO @FilterScoreDatesTable
	SELECT DISTINCT DebitRunId
	FROM Profiler.MandateScores WITH (NOLOCK)
	WHERE MandateId = @MandateId
		AND Score > 0
		AND ProfileId IN (
			'Weekday'
			,'Sat-PaySat'
			);

	WITH PositiveDRIScores (
		[DebitRunId]
		,[TotalScore]
		,[TotalScoreRanking]
		)
	AS (
		SELECT ms.[DebitRunId]
			,SUM([Score]) AS TotalScore
			,RANK() OVER (
				ORDER BY SUM([Score]) DESC
				) AS TotalScoreRanking
		FROM [Profiler].[MandateScores] ms WITH (NOLOCK)
		INNER JOIN [Profiler].[DebitRunIds] dri WITH (NOLOCK) ON dri.DebitRunId = ms.DebitRunId
		INNER JOIN [Profiler].[Profiles] profiles WITH (NOLOCK) ON profiles.ProfileId = ms.ProfileId
		INNER JOIN @FilterScoreDatesTable FT ON FT.DebitRunId = ms.DebitRunId
		WHERE [ms].[MandateId] = @MandateId
			AND [ms].[Score] > 0
			AND dri.IsDeleted = 0
			AND profiles.IsDeleted = 0
		GROUP BY ms.[DebitRunId]
		)
	SELECT [PositiveDRIScores].[DebitRunId]
		,[TotalScore]
		,(
			SELECT min([pd].[CollectionDate])
			FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
			WHERE [pd].[DebitRunId] = [PositiveDRIScores].[DebitRunId]
				AND [pd].[PaymentCycle] = @ForPaymentCycle
			) AS MinCollectionDate
		,(
			SELECT max([pd].[CollectionDate])
			FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
			WHERE [pd].[DebitRunId] = [PositiveDRIScores].[DebitRunId]
				AND [pd].[PaymentCycle] = @ForPaymentCycle
			) AS MaxCollectionDate
	FROM PositiveDRIScores
	WHERE [TotalScoreRanking] = 1
	
	UNION ALL
	
	SELECT DISTINCT ms.[DebitRunId]
		,[Score] AS TotalScore
		,(
			SELECT min([pd].[CollectionDate])
			FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
			WHERE [pd].[DebitRunId] = [ms].[DebitRunId]
				AND [pd].[PaymentCycle] = @ForPaymentCycle
			) AS MinCollectionDate
		,(
			SELECT max([pd].[CollectionDate])
			FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
			WHERE [pd].[DebitRunId] = [ms].[DebitRunId]
				AND [pd].[PaymentCycle] = @ForPaymentCycle
			) AS MaxCollectionDate
	FROM Profiler.MandateScores ms WITH (NOLOCK)
	INNER JOIN [Profiler].[DebitRunIds] dri WITH (NOLOCK) ON dri.DebitRunId = ms.DebitRunId
	INNER JOIN [Profiler].[Profiles] profiles WITH (NOLOCK) ON profiles.ProfileId = ms.ProfileId
	WHERE [ms].[MandateId] = @MandateId
		AND [ms].[Score] < 0
		AND dri.IsDeleted = 0
		AND profiles.IsDeleted = 0
		AND [ms].[ProfileId] = 'FullyCovered'
END
GO


-- ---------- Profiler.usp_GetMandateProfilesDatesForDRIs ----------
-- Pulled verbatim (CREATE -> CREATE OR ALTER only) from the upstream source of truth cited
-- above: C:/Builds/Unlimited.ProfilerServices/Database/Warewolf.ProfilerDB/Profiler/
-- Stored Procedures/usp_GetMandateProfilesDatesForDRIs.sql (WOLF-8512 - was never carried into
-- this script despite being in the .bite dependency closure; see
-- docs/ShovelBridge-Architecture.md's 2026-09-08 entry, which assumed this procedure already
-- existed and only its source tables were empty).
CREATE OR ALTER PROCEDURE [Profiler].[usp_GetMandateProfilesDatesForDRIs] (
	@MandateId UNIQUEIDENTIFIER
	,@PaymentCycle INT
	,@FromDebitRunId INT
	,@ToDebitRunId INT
	,@Day VARCHAR(2)
	)
AS
SET NOCOUNT ON

BEGIN
	DECLARE @NextPaymentCycle INT = CONVERT(INT, FORMAT(DATEADD(MONTH, 1, CONVERT(DATE, CAST(@PaymentCycle AS CHAR(6)) + '01', 102)), 'yyyyMM'));
	DECLARE @NextMaxGrantDate DATE

	SELECT TOP 1 @NextMaxGrantDate = [CollectionDate]
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	INNER JOIN [Profiler].[GrantDates] gd WITH (NOLOCK) ON gd.[Date] = pd.[CollectionDate] and gd.PaymentCycle = pd.PaymentCycle
	WHERE pd.[PaymentCycle] = @NextPaymentCycle
	ORDER BY gd.[Date] DESC

	DECLARE @MaxTrackingDate DATE
	--Fail safe if no grant days, then use @DAY if @NextMaxGrantDate is null
	SELECT TOP 1 @MaxTrackingDate = ISNULL(@NextMaxGrantDate, pd.[CollectionDate])
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	WHERE pd.[PaymentCycle] = @NextPaymentCycle
		AND pd.[CollectionDate] <= DATEADD(MONTH, 1, CONVERT(DATE, CAST(@PaymentCycle AS CHAR(6)) + @Day, 102))
	ORDER BY pd.[CollectionDate] DESC

	SELECT pd.[ProfileDateId]
		,pd.[CollectionDate]
		,pd.[DebitRunId]
		,pd.[PaymentCycle]
		,pd.[ProfileId]
		,CASE
			WHEN ms.[Score] - (
					SELECT MAX(ts.[Score])
					FROM Profiler.MandateScores ts WITH (NOLOCK)
					WHERE ts.MandateId = ms.MandateId
						AND (
							ts.ProfileId <> ms.ProfileId
							OR ts.DebitRunId <> ms.DebitRunId
							)
					) >= 2
				THEN ms.[Score]
			ELSE NULL
			END AS [Score]
		,ms.[ScoreAdjustmentReason]
	FROM Profiler.ProfileDates pd WITH (NOLOCK)
	LEFT OUTER JOIN Profiler.MandateScores ms WITH (NOLOCK) ON ms.DebitRunId = pd.DebitRunId
		AND ms.ProfileId = pd.ProfileId
		AND ms.MandateId = @MandateId
	WHERE pd.DebitRunId IN (
			@FromDebitRunId
			,@ToDebitRunId
			)
		AND pd.PaymentCycle = @PaymentCycle
		AND pd.CollectionDate <= @MaxTrackingDate
		AND pd.ProfileId NOT LIKE 'LastDay%'

	UNION ALL
	--Create End-Of-Tracking date for DRI selection
	SELECT DISTINCT TOP 1 NULL AS [ProfileDateId]
		,CASE WHEN DATEADD(DAY, CASE WHEN pd.DebitRunId NOT BETWEEN 25 AND 31
							  THEN DATEDIFF(DAY,pd.CollectionDate,calcDate.MaxCollectionDate)
								WHEN pd.DebitRunId BETWEEN 25 AND 31
							  THEN DATEDIFF(DAY, pd.[CollectionDate], @MaxTrackingDate) END, pd.[CollectionDate]) > @MaxTrackingDate
				THEN @MaxTrackingDate
			ELSE DATEADD(DAY, CASE WHEN pd.DebitRunId NOT BETWEEN 25 AND 31
						THEN DATEDIFF(DAY,pd.CollectionDate,calcDate.MaxCollectionDate)
						WHEN pd.DebitRunId BETWEEN 25 AND 31 AND DATEDIFF(DAY, pd.[CollectionDate], @MaxTrackingDate) > 10
						THEN DATEDIFF(DAY, pd.[CollectionDate], calcDate.MaxCollectionDate)
						ELSE DATEDIFF(DAY, pd.[CollectionDate], @MaxTrackingDate)
						END, pd.[CollectionDate])
			END
		,pd.[DebitRunId]
		,pd.[PaymentCycle]
		,'EndOfTracking' AS [ProfileId]
		,NULL AS [Score]
		,NULL AS [ScoreAdjustmentReason]
	FROM Profiler.ProfileDates pd WITH (NOLOCK)
	OUTER APPLY (
    SELECT MAX(p2.CollectionDate) AS MaxCollectionDate -- return correct date check public holidays and sunday
    FROM Profiler.ProfileDates p2 WITH (NOLOCK)
    WHERE p2.PaymentCycle = pd.PaymentCycle
      AND p2.CollectionDate < DATEADD(DAY, 10, pd.CollectionDate)
	) calcDate
	LEFT OUTER JOIN Profiler.MandateScores ms WITH (NOLOCK) ON ms.DebitRunId = pd.DebitRunId
		AND ms.ProfileId = pd.ProfileId
		AND ms.MandateId = @MandateId
	WHERE pd.DebitRunId IN (
			@FromDebitRunId
			,@ToDebitRunId
			)
		AND pd.PaymentCycle = @PaymentCycle
	ORDER BY pd.CollectionDate ASC
END

RETURN 0
GO


-- ---------- Profiler.usp_GetMandateProfilesDatesForDRIsInitials ----------
-- Pulled verbatim (CREATE -> CREATE OR ALTER only) from the upstream source of truth:
-- .../Warewolf.ProfilerDB/Profiler/Stored Procedures/usp_GetMandateProfilesDatesForDRIsInitials.sql
-- (WOLF-8512 - this is the procedure build 30636/30638 hit SQL Error 15009 on: it was staged as
-- a .bite workflow resource but its stored procedure body was never carried into this script).
CREATE OR ALTER PROCEDURE [Profiler].[usp_GetMandateProfilesDatesForDRIsInitials] (
	@MandateId UNIQUEIDENTIFIER
	,@PaymentCycle INT
	,@FromDebitRunId INT
	,@ToDebitRunId INT
	,@StandardTracking AS INT = 10
	)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @EarliestDate AS DATE;

	SELECT @EarliestDate = MIN(pt.CollectionDate)
	FROM Profiler.ProfileDates pt
	WHERE pt.DebitRunId IN (
			@FromDebitRunId
			,@ToDebitRunId
			)
		AND pt.PaymentCycle = @PaymentCycle;

	DECLARE @NextPaymentCycle INT = CONVERT(INT, FORMAT(DATEADD(MONTH, 1, CONVERT(DATE, CAST(@PaymentCycle AS CHAR(6)) + '01', 102)), 'yyyyMM'));
	DECLARE @NextMaxGrantDate DATE

	SELECT @NextMaxGrantDate = MAX([CollectionDate])
	FROM [Profiler].[ProfileDates] pd WITH (NOLOCK)
	INNER JOIN [Profiler].[GrantDates] gd WITH (NOLOCK) ON gd.[Date] = pd.[CollectionDate] and gd.PaymentCycle = pd.PaymentCycle
	WHERE pd.[PaymentCycle] = @NextPaymentCycle;




	WITH TrackingDates (
		CollectionDate
		,TrackingDays
		,PaymentCycle
		)
	AS (
		SELECT DISTINCT TOP (1) pd.CollectionDate
			,DATEDIFF(DAY, @EarliestDate, pd.CollectionDate) + 1 AS TrackingDays
			,pd.PaymentCycle
		FROM Profiler.ProfileDates pd WITH (NOLOCK)
		LEFT OUTER JOIN Profiler.MandateScores ms WITH (NOLOCK) ON ms.DebitRunId = pd.DebitRunId
			AND ms.ProfileId = pd.ProfileId
			AND ms.MandateId = @MandateId
		WHERE pd.CollectionDate >= @EarliestDate
			AND pd.CollectionDate <= ISNULL(@NextMaxGrantDate,DATEADD(MONTH, 1, CONVERT(DATE, CAST(pd.PaymentCycle AS VARCHAR) + '07', 102)))
			AND DATEDIFF(DAY, @EarliestDate, pd.CollectionDate) + 1 <= @StandardTracking
			AND pd.PaymentCycle = @PaymentCycle
		ORDER BY pd.CollectionDate DESC
		)
	SELECT pd.[ProfileDateId]
		,pd.[CollectionDate]
		,pd.[DebitRunId]
		,pd.[PaymentCycle]
		,pd.[ProfileId]
		,CASE
			WHEN ms.[Score] - (
					SELECT MAX(ts.[Score])
					FROM Profiler.MandateScores ts WITH (NOLOCK)
					WHERE ts.MandateId = ms.MandateId
						AND (
							ts.ProfileId <> ms.ProfileId
							OR ts.DebitRunId <> ms.DebitRunId
							)
					) >= 2
				THEN ms.[Score]
			ELSE NULL
			END AS [Score]
		,ms.[ScoreAdjustmentReason]
	FROM Profiler.ProfileDates pd WITH (NOLOCK)
	LEFT OUTER JOIN Profiler.MandateScores ms WITH (NOLOCK) ON ms.DebitRunId = pd.DebitRunId
		AND ms.ProfileId = pd.ProfileId
		AND ms.MandateId = @MandateId
	WHERE pd.DebitRunId IN (
			@FromDebitRunId
			,@ToDebitRunId
			)
		AND pd.PaymentCycle = @PaymentCycle
		AND pd.CollectionDate <= ISNULL(@NextMaxGrantDate,DATEADD(MONTH, 1, CONVERT(DATE, CAST(pd.PaymentCycle AS VARCHAR) + '07', 102)))
		AND pd.ProfileId NOT LIKE 'LastDay%'

	UNION ALL

	SELECT NULL AS [ProfileDateId]
		,CollectionDate
		,NULL AS [DebitRunId]
		,[PaymentCycle]
		,'EndOfTracking' AS [ProfileId]
		,NULL AS [Score]
		,NULL AS [ScoreAdjustmentReason]
	FROM TrackingDates
END
GO


-- ---------- Profiler.usp_CheckIfHasRecommendationType ----------
-- Pulled verbatim (CREATE -> CREATE OR ALTER only) from the upstream source of truth:
-- .../Warewolf.ProfilerDB/Profiler/Stored Procedures/usp_CheckIfHasRecommendationType.sql
-- (WOLF-8512 - called by HuntingStrategy.bite; also never carried into this script).
CREATE OR ALTER PROCEDURE [Profiler].[usp_CheckIfHasRecommendationType]
	@MandateId UNIQUEIDENTIFIER
	,@RecommendationTypes VARCHAR(MAX)
	,@PaymentCycleCountlimit INT = 24
AS
BEGIN
	SET NOCOUNT ON

	IF @PaymentCycleCountlimit IS NULL
	BEGIN
		SET @PaymentCycleCountlimit = 24
	END

	DECLARE @tblRecommendationTypes TABLE (RecommendationTypes VARCHAR(200))
	DECLARE @tblExistingRecomendationTypes TABLE (
		PaymentCycle INT
		,RecommendationType VARCHAR(200)
		)
	DECLARE @tblProfilerRecommendations TABLE (
		ProfilerRecommendationId INT
		,ForPaymentCycle INT
		,RecommendationTypes VARCHAR(200)
		)

	INSERT INTO @tblProfilerRecommendations (
		ProfilerRecommendationId
		,ForPaymentCycle
		,RecommendationTypes
		)
	SELECT TOP (@PaymentCycleCountlimit) pr.ProfilerRecommendationId
		,pr.ForPaymentCycle
		,pr.RecommendationTypes
	FROM Profiler.ProfilerRecommendation pr WITH (NOLOCK)
	WHERE pr.MandateId = @MandateId
	ORDER BY pr.ForPaymentCycle DESC

	INSERT INTO @tblRecommendationTypes (RecommendationTypes)
	SELECT VALUE
	FROM STRING_SPLIT(@RecommendationTypes, ',')

	IF EXISTS (
			SELECT TOP 1 1
			FROM @tblProfilerRecommendations pr
			INNER JOIN @tblRecommendationTypes AS t ON pr.RecommendationTypes = t.RecommendationTypes
			)
	BEGIN
		INSERT INTO @tblExistingRecomendationTypes (
			PaymentCycle
			,RecommendationType
			)
		SELECT ForPaymentCycle
			,pr.RecommendationTypes
		FROM @tblProfilerRecommendations pr
		INNER JOIN @tblRecommendationTypes AS t ON pr.RecommendationTypes = t.RecommendationTypes
	END

	IF EXISTS (
			SELECT TOP 1 1
			FROM Profiler.ProfilerRecommendationLabels pl WITH (NOLOCK)
			INNER JOIN @tblProfilerRecommendations pr ON pl.ProfilerRecommendationld = pr.ProfilerRecommendationId
			INNER JOIN @tblRecommendationTypes AS t ON pl.Label = t.RecommendationTypes
			)
	BEGIN
		INSERT INTO @tblExistingRecomendationTypes (
			PaymentCycle
			,RecommendationType
			)
		SELECT ForPaymentCycle
			,pl.Label
		FROM Profiler.ProfilerRecommendationLabels pl WITH (NOLOCK)
		INNER JOIN @tblProfilerRecommendations pr ON pl.ProfilerRecommendationld = pr.ProfilerRecommendationId
		INNER JOIN @tblRecommendationTypes AS t ON pl.Label = t.RecommendationTypes
	END

	IF EXISTS (
			SELECT TOP 1 1
			FROM @tblExistingRecomendationTypes
			)
	BEGIN
		SELECT TOP 1 'True' AS 'Exists'
			,RecommendationType AS LatestRecommendationType
		FROM @tblExistingRecomendationTypes
		ORDER BY PaymentCycle DESC
	END
	ELSE
	BEGIN
		SELECT 'False' AS 'Exists'
			,NULL AS LatestRecommendationType
	END
END
GO
-- ---------- Profiler.func_PublicHolidaysByYear ----------
-- Pulled verbatim (CREATE -> CREATE OR ALTER only) from the upstream source of truth:
-- .../Warewolf.ProfilerDB/Profiler/Functions/func_PublicHolidaysByYear.sql
-- (build 30853 - dependency of usp_GetPublicHolidaysInDateRange below. Reads Profiler.SpecialHolidays,
-- which this script already creates and seeds, so it must come after the tables.)
CREATE OR ALTER FUNCTION [Profiler].[func_PublicHolidaysByYear] (@Year INT)
RETURNS @PublicHoliday TABLE (
	PublicHolidayDate DATE
	,PublicHolidayName VARCHAR(50)
	)
AS
/*
Created by:	Ian Marran
Date:		15 Aug 2013
Detail:		This function dynamically returns a table of South African public holidays for the given year. 
			I have commented the code below to explain the dates based on non fixed Easter Sunday.
Example:	SELECT * FROM General.func_PublicHolidaysByYear(2013)
Version History
Name			Log		Date			Detail
Ian Marran		52741	15 Aug 2013		Initial function creation
*/
BEGIN
	DECLARE @GoldenNumber INT
		,@Epact INT
		,@DaysTillPaschalFullMoon INT
		,@PaschalFullMoonDayOfWeek INT
		,@Centuary INT
		,@NumOfDaysToSunday INT
		,@EasterMonth INT
		,@EasterDay INT
		,@EasterSunday DATE

	-- Complex set of rules to calculate Easter Sunday... Who would have thought we would ever bring moon phases into SQL procs? :)
	-- Generally speaking, Easter falls on the first Sunday after the first Paschal Full Moon after the 21st of March
	SET @GoldenNumber = (@Year % 19) + 1 -- How far in the cycle is the moon/year relationship (relationship between the moon's phases and the days of the year repeats itself every 19 years)
	SET @Centuary = @Year / 100
	SET @Epact = (@Centuary - (@Centuary / 4) - (((8 * @Centuary) + 13) / 25) + (19 * (@GoldenNumber - 1)) + 15) % 30 -- Measure of the age of the moon (number of days that have passed since an "official" new moon)
	SET @DaysTillPaschalFullMoon = @Epact - (@Epact / 28) * (1 - (29 / (@Epact + 1)) * ((21 - (@GoldenNumber - 1)) / 11)) -- Now that we know Epact, we can work out the days till Paschal Full Moon
	SET @PaschalFullMoonDayOfWeek = (@Year + (@Year / 4) + @DaysTillPaschalFullMoon + 2 - @Centuary + (@Centuary / 4)) % 7 -- weekday for the Paschal full moon (0=Sunday, 1=Monday, etc.)
	SET @NumOfDaysToSunday = @DaysTillPaschalFullMoon - @PaschalFullMoonDayOfWeek -- number of days from 21 March to the Sunday on or before the Paschal full moon (between -6 and 28)
	SET @EasterMonth = 3 + (@NumOfDaysToSunday + 40) / 44 -- The month easter falls in (march or april)
	SET @EasterDay = @NumOfDaysToSunday + 28 - (31 * (@EasterMonth / 4)) -- the day in that month it falls on
	SET @EasterSunday = CAST(LEFT(@Year, 4) + '-' + RIGHT('0' + CAST(@EasterMonth AS VARCHAR(2)), 2) + '-' + RIGHT('0' + CAST(@EasterDay AS VARCHAR(2)), 2) AS DATE) -- Easter Sunday represented as a date
		;

	WITH ctePublicHolidays
	AS (
		SELECT CAST(LEFT(@Year, 4) + '-01-01' AS DATE) AS PublicHoliday
			,'New Years Day' AS PublicHolidayName
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-03-21' AS DATE)
			,'Human Rights Day'
		
		UNION
		
		SELECT DATEADD(DAY, - 2, @EasterSunday)
			,'Good Friday' -- Friday before Easter
		
		UNION
		
		SELECT DATEADD(DAY, 1, @EasterSunday)
			,'Family Day' -- Monday after Easter
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-04-27' AS DATE)
			,'Freedom Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-05-01' AS DATE)
			,'Workers Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-06-16' AS DATE)
			,'Youth Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-08-09' AS DATE)
			,'National Womans Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-09-24' AS DATE)
			,'Heritage Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-12-16' AS DATE)
			,'Day Of Reconciliation'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-12-25' AS DATE)
			,'Christmas Day'
		
		UNION
		
		SELECT CAST(LEFT(@Year, 4) + '-12-26' AS DATE)
			,'Day Of Goodwill'
		)
	INSERT INTO @PublicHoliday (
		PublicHolidayDate
		,PublicHolidayName
		)
	-- The Public Holidays Act (Act No 36 of 1994) determines that whenever any public holiday falls on a Sunday, the Monday following it will be a public holiday
	SELECT DATEADD(DAY, 1, PublicHoliday) AS PublicHoliday
		,'Public Holiday' AS PublicHolidayName
	FROM ctePublicHolidays
	WHERE DATENAME(WEEKDAY, PublicHoliday) = 'Sunday' -- does the day fall on a sunday
		AND PublicHolidayName <> 'Christmas Day' -- I know 26th is a holiday anyway so dont add a monday holiday ever (this happened in 2011 and so 27th was declared a holiday but will only be decided by government at the time it happens)
	
	UNION
	
	-- All the standard holidays
	SELECT PublicHoliday
		,PublicHolidayName
	FROM ctePublicHolidays
	
	UNION
	
	SELECT [Date]
		,[HolidayName]
	FROM Profiler.SpecialHolidays with (nolock) --Static list due to the nature of Ad-Hoc public holidays
	WHERE DATEPART(YEAR,[Date]) = @Year --Ad-Hoc public holidays only ever occur once in a specific year

	RETURN
END
GO


-- ---------- Profiler.usp_GetPublicHolidaysInDateRange ----------
-- Pulled verbatim (CREATE -> CREATE OR ALTER only) from the upstream source of truth:
-- .../Warewolf.ProfilerDB/Profiler/Stored Procedures/usp_GetPublicHolidaysInDateRange.sql
-- (build 30853 - called by Profiler/V2/Private/GetTrackingPeriod.bite via its DAL wrapper, so it IS on
-- RequestForProfiling's call path. Its absence failed 54 of 200 burst messages with SQL Error 15009,
-- each returned by the engine as HTTP 500 and dead-lettered by the QueueProcessor worker.)
CREATE OR ALTER PROCEDURE [Profiler].[usp_GetPublicHolidaysInDateRange] @FromDate AS DATETIME
	,@ToDate AS DATETIME
AS
BEGIN
	IF ISNULL(@FromDate, '') <> ''
		AND ISNULL(@ToDate, '') <> ''
		SELECT 0 AS [HolidayId]
			,[PublicHolidayDate] AS [Date]
			,PublicHolidayName AS [Description]
		FROM [Profiler].[func_PublicHolidaysByYear](DATEPART(YEAR, @FromDate))
		WHERE PublicHolidayDate BETWEEN @FromDate
				AND @ToDate		
		UNION		
		SELECT 0 AS [HolidayId]
			,[PublicHolidayDate] AS [Date]
			,PublicHolidayName AS [Description]
		FROM [Profiler].[func_PublicHolidaysByYear](DATEPART(YEAR, @ToDate))
		WHERE PublicHolidayDate BETWEEN @FromDate
				AND @ToDate
	ELSE
		SELECT 0 AS [HolidayId]
			,[PublicHolidayDate] AS [Date]
			,PublicHolidayName AS [Description]
		FROM [Profiler].[func_PublicHolidaysByYear](DATEPART(YEAR, GETDATE()))
END
GO


