/* STEP 2: UPDATE existing rows */
UPDATE T
SET 
    T.CollectionDate = S.CollectionDate,
    T.DebitRunId     = S.DebitRunId,
    T.PaymentCycle   = S.PaymentCycle,
    T.ProfileId      = S.ProfileId
FROM [Profiler].[ProfileDates] T
JOIN #ProfileDatesSource S
    ON T.ProfileDateId = S.ProfileDateId;
-- NOTE: We match only on PK (ProfileDateId) for stability

/* STEP 3: INSERT new rows */
INSERT INTO [Profiler].[ProfileDates]
(
    ProfileDateId,
    CollectionDate,
    DebitRunId,
    PaymentCycle,
    ProfileId
)
SELECT 
    S.ProfileDateId,
    S.CollectionDate,
    S.DebitRunId,
    S.PaymentCycle,
    S.ProfileId
FROM #ProfileDatesSource S
LEFT JOIN [Profiler].[ProfileDates] T
    ON T.ProfileDateId = S.ProfileDateId
WHERE T.ProfileDateId IS NULL;

/* STEP 4: DELETE missing rows (same as MERGE behavior) */
DELETE T
FROM [Profiler].[ProfileDates] T
LEFT JOIN #ProfileDatesSource S
    ON T.ProfileDateId = S.ProfileDateId
WHERE S.ProfileDateId IS NULL;

